function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // tree
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 50 - 20 * Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'black';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 20 * Math.cos(i + t), H/2 - 50 - 20 * Math.sin(t) + 10 * Math.sin(i + t), 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  // roots
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 - 20 * Math.cos(t), H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 20 * Math.cos(t), H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();

  // figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100 * Math.cos(t), H - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 * Math.cos(t), H - 50);
  ctx.lineTo(W/2 + 100 * Math.cos(t), H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 * Math.cos(t), H - 100);
  ctx.lineTo(W/2 + 100 * Math.cos(t) - 20, H - 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 * Math.cos(t), H - 100);
  ctx.lineTo(W/2 + 100 * Math.cos(t) + 20, H - 150);
  ctx.stroke();

  ctx.restore();
}
